using EqlTracker.Core;
using EqlTracker.Companion;

internal static class IntegratedCompanionTests
{
    internal static void Register(Action<string, Action> test)
    {
        void Check(bool value, string message = "Integrated feature assertion failed") { if (!value) throw new Exception(message); }
        EffectInput Effect(string id, string family, double? amount, EffectChannel channel = EffectChannel.Attribute, bool equipment = false) => new() { Identity = new(id, id, 0), Family = family, Amount = amount, Channel = channel, Quality = amount.HasValue ? EvidenceQuality.UserConfirmed : EvidenceQuality.Unknown, Equipment = equipment, Source = "Synthetic reviewed evidence", DisplayUnitsConfirmed = true };
        EvaluationContext Pet(double? observed = null) => new() { SummonedPet = true, PetLevel = 50, SpeedEvidence = observed.HasValue ? EvidenceQuality.UserConfirmed : EvidenceQuality.Unknown, ObservedOrdinaryAttackSpeed = observed, SpeedSource = "Synthetic reviewed paired inspection",ReviewedOrdinaryCeiling=171,Fingerprint="synthetic-exact-context",CeilingFingerprint="synthetic-exact-context",Patch=PetDefinition.Version };
        EffectRule Rule(EffectRuleKind kind, string family, string[] spells, string winner = "") => new() { Id = "fixture-rule", Kind = kind, Family = family, SpellIds = spells.ToList(), Winner = winner, Source = "Synthetic reviewed experiment", Quality = EvidenceQuality.UserConfirmed };
        test("Compatibility scoped 171 ceiling uses displayed units and retains non-haste", () => {
            var context = Pet(171); var a = Effect("cloak", "Haste", 20, EffectChannel.WornHaste, true); var b = Effect("cloak2", "Haste", 30, EffectChannel.WornHaste, true);
            var result = BuildCompatibility.Compare(context, [a], [b, Effect("cloak2", "HP", 50, equipment: true)], []);
            Check(result.Conclusion.StartsWith("No additional ordinary")); Check(result.Changes.Single(c => c.Family == "HP/Attribute").UsableChange == 50); Check(result.Changes.Single(c => c.Family == "Ordinary displayed attack speed").UsableChange == 0); Check(result.After.Notes.Any(n => n.Contains("hidden overflow"))); });
        test("Compatibility below-cap gain requires confirmed display conversion", () => { var context = Pet(); context.DisplayCompositionConfirmed = true; context.OrdinaryDisplayBaseline = 100; var a = Effect("a", "Haste", 20, EffectChannel.WornHaste, true); var b = Effect("b", "Haste", 40, EffectChannel.WornHaste, true); var result = BuildCompatibility.Compare(context, [a], [b], []); Check(result.Before.OrdinaryAttackSpeed == 120 && result.After.OrdinaryAttackSpeed == 140); });
        test("Compatibility cap boundary clamps 170 to 171 without extending scope", () => { var context = Pet(); context.DisplayCompositionConfirmed = true; context.OrdinaryDisplayBaseline = 100; var a = Effect("a", "Haste", 70, EffectChannel.WornHaste, true); var b = Effect("b", "Haste", 90, EffectChannel.WornHaste, true); var result = BuildCompatibility.Compare(context, [a], [b], []); Check(result.Before.OrdinaryAttackSpeed == 170 && result.After.OrdinaryAttackSpeed == 171); });
        test("Compatibility lower-level charmed and Self never inherit summoned cap", () => { foreach (string kind in new[] { "lower", "charmed", "self", "unknown" }) { var context = Pet(171); if (kind == "lower") context.PetLevel = 49; if (kind == "charmed") context.CharmedPet = true; if (kind == "self") context.SummonedPet = false; if (kind == "unknown") context.PetLevel = null; var result = BuildCompatibility.Compare(context, [Effect("a", "Haste", 20, EffectChannel.WornHaste, true)], [Effect("b", "Haste", 30, EffectChannel.WornHaste, true)], []); Check(!result.After.OrdinaryCapApplies && !result.Conclusion.StartsWith("No additional ordinary")); } });
        test("Compatibility capped display never establishes safe reductions", () => { var result = BuildCompatibility.Compare(Pet(171), [Effect("a", "Haste", 30, EffectChannel.WornHaste, true)], [Effect("b", "Haste", 20, EffectChannel.WornHaste, true)], []); Check(!result.Conclusion.StartsWith("No additional ordinary")); });
        test("Compatibility overhaste remains separately unresolved", () => { var result = BuildCompatibility.Evaluate(Pet(171), [Effect("over", "Overhaste", 10, EffectChannel.Overhaste)], []); Check(result.Contributions.Single().State == ContributionState.Unresolved && result.Notes.Any(n => n.Contains("Overhaste"))); });
        test("Compatibility whole-buff blocking excludes every component", () => { var effects = new[] { Effect("strong", "Haste", 60), Effect("weak", "Haste", 30), Effect("weak", "AC", 20) }; var result = BuildCompatibility.Evaluate(new(), effects, [Rule(EffectRuleKind.BlocksWholeSpell, "", ["strong", "weak"], "strong")]); Check(result.Contributions.Count(c => c.State == ContributionState.Blocked) == 2); Check(!result.Totals.ContainsKey("AC/Attribute")); });
        test("Compatibility partial redundancy preserves useful song components", () => { var result = BuildCompatibility.Evaluate(new(), [Effect("a", "Haste", 60), Effect("b", "Haste", 30), Effect("b", "AC", 20)], [Rule(EffectRuleKind.Strongest, "Haste", ["a", "b"])]); Check(result.Contributions.Single(c => c.Effect.Identity.SpellId == "b" && c.Effect.Family == "Haste").State == ContributionState.Replaced); Check(result.Contributions.Single(c => c.Effect.Family == "AC").Usable == 20); });
        test("Compatibility rank-context rules do not generalize and unknown is not zero", () => { var rule = Rule(EffectRuleKind.Sum, "STR", ["a", "b"]); rule.Ranks["a"] = 0; rule.ContextFingerprint = "reviewed"; var a = Effect("a", "STR", 10); var b = Effect("b", "STR", 20); var result = BuildCompatibility.Evaluate(new() { Fingerprint = "other" }, [a,b], [rule]); Check(result.Totals["STR/Attribute"] == null); var comparison = BuildCompatibility.Compare(new(), [a], [Effect("unsupported", "STR", null)], []); Check(!comparison.CanClaimUpgrade && comparison.Changes.Single().UsableChange == null); });
        test("Compatibility sustained scenario excludes Frenzied burst contribution", () => { var burst = Effect("Frenzied", "Haste", 100); burst.Burst = true; Check(BuildCompatibility.Evaluate(new() { Scenario = "Usual buffs" }, [burst], []).Contributions.Count == 0); });
        test("Bard Aura one-to-five slots select from final gem backward", () => { for (int rank = 1; rank <= 5; rank++) { var setup = new BardSetup { ConfirmedAuraRank = rank, AuraEvidence = "fixture", Songs = Enumerable.Range(1,8).Select(n => new BardSong { Gem = n, Identity = new(n.ToString(), "Song", 0), Mana = 0, CooldownMs = 0, NonTargetedArea = true }).ToList() }; Check(BardCoverage.AuraSelection(setup).Select(s => s.Gem).SequenceEqual(Enumerable.Range(0,rank).Select(n => 8-n))); } });
        test("Bard invalid songs and unknown AA are not assumed eligible", () => { var setup = new BardSetup { Songs = [new() { Gem = 8, Mana = 1, CooldownMs = 0, NonTargetedArea = true }] }; Check(BardCoverage.AuraSelection(setup).Count == 0); setup.ConfirmedAuraRank = 5; setup.AuraEvidence = "fixture"; Check(BardCoverage.AuraSelection(setup).Count == 0); setup.Songs[0].Mana = 0; setup.Songs[0].CooldownMs = null; Check(BardCoverage.AuraSelection(setup).Count == 0); });
        test("Bard attempts stale and wrong-recipient coverage withdraw advice", () => { var now = DateTime.UtcNow; var observation = new CoverageObservation { Caster = "Bard", Recipient = "Pet", At = now.AddSeconds(-1), Until = now.AddSeconds(5), SuccessfulApplication = true, Attribution = EvidenceQuality.Observed }; Check(!observation.Fresh(now, "Self")); observation.Recipient = "Self"; observation.SuccessfulApplication = false; Check(!observation.Fresh(now, "Self")); observation.SuccessfulApplication = true; observation.Until = now; Check(!observation.Fresh(now, "Self")); });
        test("Bard non-redundant components and Keep prohibit swaps", () => { var setup = new BardSetup { ConfirmedAuraRank = 1, AuraEvidence = "fixture", Songs = [new() { Gem = 8, Keep = true, Mana = 0, CooldownMs = 0, NonTargetedArea = true, Identity = new("a", "a", 0) }], Available = [new() { Identity = new("b", "b", 0), Available = true }] }; Check(BardCoverage.Evaluate(setup, [], new HashSet<string>(), new(), [], DateTime.UtcNow).Suggestions.Count == 0); CheckThrows(() => BardCoverage.SavePlan(setup, new(8, new("a", "a", 0), new("b", "b", 0), "", []), DateTime.Now)); });
        test("Journal same-second receipts deduplicate by identity and keep automatic sales", () => { var at = DateTime.Now; var catalog = new Catalog { Items = [new() { Key = "gem", Name = "Gem" }] }; var a = ActivityJournal.Receipt("1:1", new(at, "Gem", "Sold", 1, "a giant"), "Zone (Solo)", catalog, null); var b = ActivityJournal.Receipt("1:2", new(at, "Gem", "Merged", 1, "a giant", "Gem +1"), "Zone (Solo)", catalog, null); var group = ActivityJournal.Loot([a,a,b], null).Single(); Check(group.Quantity == 2 && group.Receipts.Count == 2 && group.Disposition.Contains("Sold")); Check(!a.PurposeRecorded); });
        test("Journal persistence and checkpoint are atomic and replay-safe", () => { string path = Path.Combine(Path.GetTempPath(), "catalyst-journal-"+Guid.NewGuid()+".db"); using (var store = new TrackerStore(path)) { var activity = new JournalActivity { Id = "1:1:item", At = DateTime.Now, Acquisition = true, Kind = "Item", Name = "Gem", Quantity = 1 }; for (int n=0;n<2;n++) store.Commit(new() { Offset = 42 },new(),new(),[],null,[],activity:[activity]); Check(store.LoadActivities().Count == 1 && store.Get<FileCheckpoint>("checkpoint")!.Offset == 42); } using(var store = new TrackerStore(path)) Check(store.LoadActivities().Single().Quantity == 1); Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools(); File.Delete(path); });
        test("Journal keyset paging preserves same-second identities", () => { string path = Path.Combine(Path.GetTempPath(), "catalyst-page-"+Guid.NewGuid()+".db"); using(var store=new TrackerStore(path)) { var at=DateTime.Now; store.SaveActivities(Enumerable.Range(1,5).Select(n=>new JournalActivity { Id=n.ToString(), At=at })); var first=store.LoadActivities(limit:2); var second=store.LoadActivities(first[^1].At,first[^1].Id,2); Check(first.Concat(second).Select(a=>a.Id).Distinct().Count()==4); } Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools(); File.Delete(path); });
        test("Camp shared source identity preserves zone variants and one persisted estimate", () => { var book=new CampNotebook(); var a=new ItemSource { Zone="Zone (Solo)", Mob="Mob" }; var b=new ItemSource { Zone="Zone (Raid)", Mob="Mob" }; Check(CampNotebook.Key(a)!=CampNotebook.Key(b)); book.Get(a).Notes="shared"; Check(book.Get(a).Notes=="shared"); book.Start(a,DateTime.Now.AddMinutes(-10),TimeSpan.FromMinutes(1)); Check(book.Timer!.Label(DateTime.Now)=="Estimate elapsed"); book.Start(b,DateTime.Now,TimeSpan.FromMinutes(1)); Check(book.Timer.SourceId==CampNotebook.Key(b)); });
        test("Holdings only publish physical evidence and preserve extracted identity", () => { var summary=HoldingsSummary.From(new() {Character="Alt",Server="test"},new(){CapturedAt=DateTime.Now,Entries=[new(){Name="Cloak +3",Count=2,Location="Bank"},new(){Name="Cloak (Exaltation)",Count=1,Location="Augmentation"}]},new()); Check(summary.Items.Count==2 && summary.Items.Count(i=>i.Extracted)==1 && summary.Items[0].Rank==3); });
        test("Recap plans remain plans and unknown income is not zero", () => { var at=DateTime.Now; var session=new PlaySession { Start=at, LastObserved=at.AddHours(1), Inferred=true }; var recap=SessionRecap.Build(session,[new(){Id="plan",At=at,Kind="Planned setup",Name="Swap"}],[]); Check(recap.Setup.Single().Kind=="Planned setup" && recap.Coin==null && recap.Session.Inferred); });
        test("Pairing expires consumes challenge once and never authorizes before approval", () => { var now=DateTimeOffset.UtcNow; var authority=new PairingAuthority(clock:()=>now); string challenge=authority.CreateChallenge(); var ticket=authority.Request(new(challenge,"Phone","android",1))!; Check(authority.Request(new(challenge,"Other","android",1))==null); Check(authority.Poll(new(ticket.RequestId,ticket.PollSecret)).Credential==null); now=now.AddMinutes(3); Check(!authority.Approve(ticket.RequestId,"hero")); Check(authority.Poll(new(ticket.RequestId,ticket.PollSecret)).Status=="Expired"); });
        test("Pairing approved credentials are verifier-only separately revocable and scoped", () => { IReadOnlyList<CompanionDevice>? persisted=null; var authority=new PairingAuthority(persist:d=>persisted=d); var ticket=authority.Request(new(authority.CreateChallenge(),"Phone","android",1))!; Check(authority.Approve(ticket.RequestId,"hero")); var outcome=authority.Poll(new(ticket.RequestId,ticket.PollSecret)); string credential=outcome.Credential!; var device=authority.Authenticate(credential,"android")!; Check(device.Contexts.SetEquals(["hero"]) && !device.ShareHoldings && persisted!.Single().Verifier!=credential); Check(authority.Authenticate(credential,"browser")==null); bool revoked=false; authority.Revoked+=id=>revoked=id==device.Id; authority.Revoke(device.Id); Check(revoked && authority.Authenticate(credential,"android")==null); Check(authority.Poll(new(ticket.RequestId,ticket.PollSecret)).Credential==null); });
        test("Pairing wrong poll secrets unsupported protocols and unknown devices fail closed", () => { var authority=new PairingAuthority(); Check(authority.Request(new(authority.CreateChallenge(),"Phone","android",2))==null); var ticket=authority.Request(new(authority.CreateChallenge(),"Phone","android",1))!; Check(authority.Poll(new(ticket.RequestId,"wrong")).Status=="Expired"); Check(authority.Authenticate("unknown","android")==null); });
        test("Phone holdings require explicit character and holdings permission", () => { var section=new CompanionSection("",[]); var snapshot=new CompanionSnapshot(1,DateTimeOffset.UtcNow,"hero","Hero",new Dictionary<string,string>(),section,section,section,new("Holdings",[new("Alt item","1",Id:"alt")])); var device=new CompanionDevice {Contexts=["hero"],ShareHoldings=true}; Check(snapshot.ForDevice(device).Holdings.Rows.Count==0); device.Contexts.Add("alt"); Check(snapshot.ForDevice(device).Holdings.Rows.Count==1); device.ShareHoldings=false; Check(snapshot.ForDevice(device).Holdings.Rows.Count==0); });
    }
    private static void CheckThrows(Action action) { try { action(); } catch (InvalidDataException) { return; } throw new Exception("Expected validation rejection"); }
}
